import{currentUserRole}from"@/lib/role";import{redirect}from"next/navigation";import VendorClient from"./VendorClient";import Link from"next/link";export default async function Vendor(){const{user,role,s}=await currentUserRole();if(!user)redirect("/auth");if(role==="admin")redirect("/admin");if(role!=="vendor")redirect("/");const{data:v}=await s.from("vendor_profiles").select("*").eq("user_id",user.id).maybeSingle();if(!v)return <main className="shell"><h1>Vendor portal</h1><p>No vendor profile found.</p></main>;const{data:o}=await s.from("orders").select("*").eq("vendor_user_id",user.id).in("status",["offered","accepted","preparing","out_for_delivery"]).order("created_at",{ascending:false});return <main className="shell"><div className="brand">PET<span>HOC</span></div><p className="muted">Vendor portal</p><h1>Dashboard</h1><VendorClient vendor={v} orders={o||[]}/><nav className="nav"><Link href="/vendor">Dashboard</Link><Link href="/vendor/history">History</Link><Link href="/vendor/earnings">Earnings</Link><Link href="/profile">Profile</Link></nav></main>}